CREATE DATABASE IF NOT EXISTS shopsphere CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE shopsphere;
CREATE TABLE IF NOT EXISTS users (user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,mobile VARCHAR(20),role ENUM('CUSTOMER','ADMIN') NOT NULL DEFAULT 'CUSTOMER',status BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS addresses(address_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,address_line VARCHAR(255) NOT NULL,city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,pincode VARCHAR(15) NOT NULL,address_type VARCHAR(30) DEFAULT 'HOME',FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS categories(category_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500),status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products(product_id INT AUTO_INCREMENT PRIMARY KEY,category_id INT, name VARCHAR(180) NOT NULL,brand VARCHAR(90),description TEXT,price DECIMAL(12,2) NOT NULL,discount DECIMAL(5,2) DEFAULT 0,stock INT NOT NULL DEFAULT 0,image_url VARCHAR(500),status BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(category_id),CHECK(price >= 0),CHECK(stock >= 0),CHECK(discount BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS cart(cart_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL DEFAULT 1,UNIQUE KEY uq_cart(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(product_id) REFERENCES products(product_id),CHECK(quantity > 0));
CREATE TABLE IF NOT EXISTS wishlist(wishlist_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_wish(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS coupons(coupon_id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,discount_type ENUM('PERCENT','FIXED') NOT NULL,discount_value DECIMAL(12,2) NOT NULL,minimum_order DECIMAL(12,2) DEFAULT 0,maximum_discount DECIMAL(12,2),expiry_date DATE,status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders(order_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,address_id INT NOT NULL,total_amount DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) DEFAULT 0,payment_method VARCHAR(30) NOT NULL,payment_status VARCHAR(30) DEFAULT 'PENDING',order_status VARCHAR(30) DEFAULT 'PLACED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(address_id) REFERENCES addresses(address_id));
CREATE TABLE IF NOT EXISTS order_items(order_item_id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,price DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(order_id),FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,order_id INT UNIQUE NOT NULL,payment_method VARCHAR(30),transaction_reference VARCHAR(100),amount DECIMAL(12,2),payment_status VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(order_id));
CREATE TABLE IF NOT EXISTS reviews(review_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,rating INT NOT NULL,review_text TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(product_id) REFERENCES products(product_id),CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS coupon_usage(usage_id INT AUTO_INCREMENT PRIMARY KEY,coupon_id INT NOT NULL,user_id INT NOT NULL,order_id INT NOT NULL,used_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_coupon_order(coupon_id,order_id),FOREIGN KEY(coupon_id) REFERENCES coupons(coupon_id),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(order_id) REFERENCES orders(order_id));
